import time

attempts = {}

def check_login(username, password, correct_password):
    now = time.time()
    if username in attempts:
        last_time, count = attempts[username]
        if count >= 5 and now - last_time < 60:
            return False, "Too many attempts"
    if password == correct_password:
        attempts.pop(username, None)
        return True, "OK"
    else:
        last_time, count = attempts.get(username, (now, 0))
        attempts[username] = (now, count + 1)
        return False, "Invalid credentials"
